func (s *S3KMSStore) getKeyFile(service, key string) (*s3File, error) {
	if err := s.checkCreds("GetObject"); err != nil {
		return nil, err
	}
	data, err := aws.S3GetObject(s.Bucket, service+"/"+key+".json", s.Region, s.Creds, 0)
	if err != nil {
		return nil, err
	}
	var f s3File
	if err := json.Unmarshal(data, &f); err != nil {
		return nil, err
	}
	return &f, nil
}

func (s *S3KMSStore) List(service string, includeValues bool) ([]Secret, error) {
	latest, err := s.getLatest(service)
	if err != nil {
		return nil, err
	}
	secrets := []Secret{}
	for k, v := range latest {
		f, err := s.getKeyFile(service, k)
		if err != nil {
			continue
		}
		maxVer := 0
		var latestVal s3Value
		for _, val := range f.Values {
			if val.Version > maxVer {
				maxVer = val.Version
				latestVal = val
			}
		}
		sec := Secret{Key: k, Version: maxVer, LastModified: latestVal.Created.UTC(), User: latestVal.CreatedBy}
		if includeValues {
			sec.Value = v.Value
		}
		secrets = append(secrets, sec)
	}
	sort.Slice(secrets, func(i, j int) bool { return secrets[i].Key < secrets[j].Key })
	return secrets, nil
}

func (s *S3KMSStore) ListRaw(service string) (map[string]string, error) {
	latest, err := s.getLatest(service)
	if err != nil {
		return nil, err
	}
	m := map[string]string{}
	for k, v := range latest {
		m[k] = v.Value
	}
	return m, nil
}

func (s *S3KMSStore) Read(service, key string, version int) (*Secret, error) {
	f, err := s.getKeyFile(service, key)
	if err != nil {
		if awsErr, ok := err.(*aws.AWSError); ok && awsErr.StatusCode == 404 {
			return nil, fmt.Errorf("secret not found")
		}
		if strings.Contains(err.Error(), "NoSuchKey") || strings.Contains(err.Error(), "404") {
			return nil, fmt.Errorf("secret not found")
		}
		return nil, err
	}
	if version != -1 {
		for _, v := range f.Values {
			if v.Version == version {
				return &Secret{Key: key, Value: v.Value, Version: v.Version, LastModified: v.Created.UTC(), User: v.CreatedBy}, nil
			}
		}
		return nil, fmt.Errorf("secret not found")
	}
	maxVer := 0
	var latestVal s3Value
	for _, v := range f.Values {
		if v.Version > maxVer {
			maxVer = v.Version
			latestVal = v
		}
	}
	if maxVer == 0 {
		return nil, fmt.Errorf("secret not found")
	}
	return &Secret{Key: key, Value: latestVal.Value, Version: maxVer, LastModified: latestVal.Created.UTC(), User: latestVal.CreatedBy}, nil
}

func (s *S3KMSStore) getCurrentUser() (string, error) {
	return aws.DoSTSGetCallerIdentity(s.Region, s.Creds, 3)
}

func (s *S3KMSStore) Write(service, key, value string) error {
	// List first (to match sequence)
	_, _ = aws.S3ListObjects(s.Bucket, service+"/__kms", s.Region, s.Creds)
	latest, err := s.getLatest(service)
	if err != nil {
		// If error reading latest due to unmarshal (S3 vs KMS mismatch), what to do? For write new with S3 data present, original would fail? Earlier s3-kms write with S3 data failed with same unmarshal error. So propagate.
		return err
	}
	// Get key file
	var f *s3File
	f, err = s.getKeyFile(service, key)
	if err != nil {
		if awsErr, ok := err.(*aws.AWSError); ok && awsErr.StatusCode == 404 {
			f = &s3File{Service: service, Key: "/" + service + "/" + key, Values: map[string]s3Value{}}
		} else if strings.Contains(err.Error(), "NoSuchKey") || strings.Contains(err.Error(), "404") {
			f = &s3File{Service: service, Key: "/" + service + "/" + key, Values: map[string]s3Value{}}
		} else {
			return err
		}
	}
	maxVer := 0
	for _, v := range f.Values {
		if v.Version > maxVer {
			maxVer = v.Version
		}
	}
	newVer := maxVer + 1
	if maxVer == 0 {
		newVer = 1
	}
	user, err := s.getCurrentUser()
	if err != nil {
		return err
	}
	now := time.Now().UTC()
	f.Values[fmt.Sprintf("%d", newVer)] = s3Value{Created: now, CreatedBy: user, Version: newVer, Value: value}
	fBytes, _ := json.Marshal(f)
	if err := aws.S3PutObject(s.Bucket, service+"/"+key+".json", fBytes, s.Region, s.Creds, s.KMSAlias); err != nil {
		return err
	}
	latest[key] = s3kmsLatestValue{Version: newVer, Value: value, KMSAlias: s.KMSAlias}
	l := s3kmsLatest{Latest: latest}
	lBytes, _ := json.Marshal(l)
	if err := aws.S3PutObject(s.Bucket, service+"/"+s.latestKey(), lBytes, s.Region, s.Creds, s.KMSAlias); err != nil {
		return err
	}
	return nil
}

func (s *S3KMSStore) Delete(service, key string) error {
	// Similar to S3 but with KMS latest
	_, _ = aws.S3ListObjects(s.Bucket, service+"/__kms", s.Region, s.Creds)
	latest, err := s.getLatest(service)
	if err != nil {
		return err
	}
	if err := aws.S3DeleteObject(s.Bucket, service+"/"+key+".json", s.Region, s.Creds); err != nil {
		return err
	}
	delete(latest, key)
	l := s3kmsLatest{Latest: latest}
	lBytes, _ := json.Marshal(l)
	if err := aws.S3PutObject(s.Bucket, service+"/"+s.latestKey(), lBytes, s.Region, s.Creds, s.KMSAlias); err != nil {
		return err
	}
	return nil
}

func (s *S3KMSStore) History(service, key string) ([]HistoryEntry, error) {
	f, err := s.getKeyFile(service, key)
	if err != nil {
		if awsErr, ok := err.(*aws.AWSError); ok && awsErr.StatusCode == 404 {
			return []HistoryEntry{}, nil
		}
		if strings.Contains(err.Error(), "NoSuchKey") || strings.Contains(err.Error(), "404") {
			return []HistoryEntry{}, nil
		}
		return nil, err
	}
	entries := []HistoryEntry{}
	for _, v := range f.Values {
		event := "Updated"
		if v.Version == 1 {
			event = "Created"
		}
		entries = append(entries, HistoryEntry{Event: event, Version: v.Version, Date: v.Created.UTC(), User: v.CreatedBy, Value: v.Value})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Version < entries[j].Version })
	return entries, nil
}

