	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func init() {
	rootCmd.PersistentFlags().StringVarP(&backendFlag, "backend", "b", "ssm", "Backend to use; AKA $CHAMBER_SECRET_BACKEND\n\tnull: no-op\n\tssm: SSM Parameter Store\n\tsecretsmanager: Secrets Manager\n\ts3: S3; requires --backend-s3-bucket\n\ts3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).")
	rootCmd.PersistentFlags().StringVar(&s3BucketFlag, "backend-s3-bucket", "", "bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	rootCmd.PersistentFlags().StringVar(&kmsAliasFlag, "kms-key-alias", "alias/parameter_store_key", "KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
	rootCmd.PersistentFlags().IntVarP(&retriesFlag, "retries", "r", 10, "For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	rootCmd.PersistentFlags().StringVar(&retryModeFlag, "retry-mode", "standard", "For SSM, the model used to retry requests\n  standard\n  adaptive")
	rootCmd.PersistentFlags().BoolVar(&verboseFlag, "verbose", false, "Print more information to STDERR")
	rootCmd.CompletionOptions.DisableDefaultCmd = true
}

func getRetries(cmd *cobra.Command) (int, error) {
	changed := cmd.Root().PersistentFlags().Changed("retries")
	if changed {
		return retriesFlag, nil
	}
	if v := os.Getenv("CHAMBER_RETRIES"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil {
			return 0, fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
		}
		return n, nil
	}
	return retriesFlag, nil
}

func getBackendName(cmd *cobra.Command) string {
	changed := cmd.Root().PersistentFlags().Changed("backend")
	if changed {
		return backendFlag
	}
	if v := os.Getenv("CHAMBER_SECRET_BACKEND"); v != "" {
		return v
	}
	return backendFlag
}

func getS3Bucket(cmd *cobra.Command) string {
	changed := cmd.Root().PersistentFlags().Changed("backend-s3-bucket")
	if changed {
		return s3BucketFlag
	}
	if v := os.Getenv("CHAMBER_S3_BUCKET"); v != "" {
		return v
	}
	return s3BucketFlag
}

func getRetryMode(cmd *cobra.Command) string {
	return retryModeFlag
}

func getKMSAlias(cmd *cobra.Command) (string, bool) {
	changed := cmd.Root().PersistentFlags().Changed("kms-key-alias")
	return kmsAliasFlag, changed
}

func GetStore(cmd *cobra.Command) (store.Store, error) {
	backendName := getBackendName(cmd)
	backendUpper := strings.ToUpper(backendName)
	backendLower := strings.ToLower(backendName)
	retries, err := getRetries(cmd)
	if err != nil {
		return nil, err
	}
	retryMode := getRetryMode(cmd)
	kmsVal, kmsChanged := getKMSAlias(cmd)
	s3Bucket := getS3Bucket(cmd)

	switch backendLower {
	case "null":
		return &store.NullStore{}, nil
	case "ssm":
		if retryMode != "standard" && retryMode != "adaptive" {
			return nil, fmt.Errorf("Invalid retry mode %s", retryMode)
		}
		if kmsVal != "alias/parameter_store_key" {
			return nil, fmt.Errorf("Unable to use --kms-key-alias with this backend. Use CHAMBER_KMS_KEY_ALIAS instead.")
		}
		st, err := store.NewSSMStore(retries)
		if err != nil {
			return nil, err
		}
		_ = retryMode
		return st, nil
	case "secretsmanager":
		st, err := store.NewSecretsManagerStore(retries)
		if err != nil {
			return nil, err
		}
		return st, nil
	case "s3":
		if kmsVal != "alias/parameter_store_key" {
			return nil, fmt.Errorf("Unable to use --kms-key-alias with this backend.")
		}
		st, err := store.NewS3Store(s3Bucket)
		if err != nil {
			return nil, err
		}
		return st, nil
	case "s3-kms", "s3kms":
		var alias string
		if kmsChanged {
			alias = kmsVal
		} else if v := os.Getenv("CHAMBER_KMS_KEY_ALIAS"); v != "" {
			alias = v
		} else {
			alias = kmsVal
		}
		st, err := store.NewS3KMSStore(s3Bucket, alias, kmsChanged)
		if err != nil {
			return nil, err
		}
		return st, nil
	default:
		return nil, fmt.Errorf("invalid backend `%s`", backendUpper)
	}
}

func fail(err error) {
	fmt.Fprintf(os.Stderr, "Error: %v\n", err)
	os.Exit(1)
}

func failWithPrefix(prefix string, err error) {
	fmt.Fprintf(os.Stderr, "Error: %s: %v\n", prefix, err)
	os.Exit(1)
}
