python3 /tmp/srvWrite.py > /tmp/logWrite.txt 2>&1 &
echo $! > /tmp/pidWrite
sleep 1
export AWS_ACCESS_KEY_ID=test AWS_SECRET_ACCESS_KEY=test AWS_REGION=us-east-1 AWS_ENDPOINT_URL=http://127.0.0.1:18184
test_pair() {
  desc="$1"; shift
  echo -n "[$desc]: "
  /workspace/executable --retries 1 "$@" > /tmp/o1.txt 2> /tmp/e1.txt; e1=$?
  /tmp/testbuild --retries 1 "$@" > /tmp/o2.txt 2> /tmp/e2.txt; e2=$?
  if [ "$e1" != "$e2" ]; then echo "EXIT $e1 vs $e2"; echo "orig err:"; cat /tmp/e1.txt; echo "new err:"; cat /tmp/e2.txt;
  else if diff -q /tmp/o1.txt /tmp/o2.txt > /dev/null && diff -q /tmp/e1.txt /tmp/e2.txt > /dev/null; then echo "MATCH"; else echo "DIFF"; echo "orig out:"; cat /tmp/o1.txt; echo "new out:"; cat /tmp/o2.txt; echo "orig err:"; cat /tmp/e1.txt; echo "new err:"; cat /tmp/e2.txt; fi; fi
}
test_pair "write new tags" write mysvc newkey newval -t k1=v1
test_pair "write existing tags" write mysvc existing newval -t k1=v1
test_pair "write skip same" write --skip-unchanged mysvc existing old
test_pair "write skip diff" write --skip-unchanged mysvc existing newval
test_pair "read version" read --version 1 mysvc existing
test_pair "delete" delete mysvc existing
test_pair "export file" export mysvc -o /tmp/exp1.json
# Compare export files? Both write to same file, need separate
rm -f /tmp/exp1.json /tmp/exp2.json
/workspace/executable --retries 1 export mysvc -o /tmp/exp1.json > /tmp/o1.txt 2> /tmp/e1.txt
/tmp/testbuild --retries 1 export mysvc -o /tmp/exp2.json > /tmp/o2.txt 2> /tmp/e2.txt
if diff -q /tmp/exp1.json /tmp/exp2.json > /dev/null && diff -q /tmp/o1.txt /tmp/o2.txt > /dev/null && diff -q /tmp/e1.txt /tmp/e2.txt > /dev/null; then echo "[export file]: MATCH"; else echo "[export file]: DIFF"; cat /tmp/exp1.json; cat /tmp/exp2.json; fi
kill $(cat /tmp/pidWrite)
sleep 1; echo done
'"}

